   218	void *BUF_memdup(const void *data, size_t size) {
   219	  if (size == 0) {
   220	    return NULL;
   221	  }
   222	
   223	  void *ret = OPENSSL_malloc(size);
   224	  if (ret == NULL) {
   225	    OPENSSL_PUT_ERROR(BUF, ERR_R_MALLOC_FAILURE);
   226	    return NULL;
   227	  }
   228	
   229	  OPENSSL_memcpy(ret, data, size);
   230	  return ret;
   231	}
